// src/theme.js
import { createTheme } from '@mui/material';

export const theme = createTheme({
  palette: {
    mode: 'dark', // <-- دي أهم حاجة لتفعيل الوضع الداكن
    primary: {
      main: '#2C3E50',
    },
    secondary: {
      main: '#E67E22',
    },
    background: {
      default: '#121212',
      paper: '#1E1E1E',
    },
  },
});
